export interface LibraryBookRef {
  book: LibraryBook;
  collection: LibraryCollection;
  /** The level that applies to this book (its own, or the collection's shared one). */
  level: LibraryLevel | undefined;
}
// ---------- derived helpers (no data editing required below this line) ----------

/** Unique id of a book within the library: "<collectionId>/<bookId>". */
export function bookKey(collectionId: string, bookId: string): string {
  return `${collectionId}/${bookId}`;
}

export function findBook(key: string): LibraryBookRef | undefined {
  const [collectionId, bookId] = key.split('/');
  if (!bookId) return undefined;
  const collection = WORD_LIBRARY.find((c) => c.id === collectionId);
  if (!collection) return undefined;
  const book = collection.books.find((b) => b.id === bookId);
  if (!book) return undefined;
  return { book, collection, level: book.level ?? collection.level };
}

/** Every word in a collection across all its books. */
export function collectionWords(collection: LibraryCollection): LibraryWord[] {
  return collection.books.flatMap((b) => b.words);
}

/** Distinct levels across a collection's books; empty when none are tagged. */
export function collectionLevels(collection: LibraryCollection): LibraryLevel[] {
  return Array.from(new Set(collection.books.map((b) => b.level ?? collection.level).filter(Boolean))) as LibraryLevel[];
}

/** True when a collection's books sit at different levels → "Mixed levels" badge. */
export function isMixedLevels(collection: LibraryCollection): boolean {
  return collectionLevels(collection).length > 1;
}
